from typing import Annotated

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException

app = FastAPI()


def require_member(authorization: Annotated[str | None, Header()] = None) -> str:
    if authorization is None:
        raise HTTPException(status_code=401, detail="Missing bearer token")
    scheme, _, token = authorization.partition(" ")
    if scheme.lower() != "bearer" or token != "member-token":
        raise HTTPException(status_code=403, detail="Member role required")
    return token


members = APIRouter(prefix="/members", dependencies=[Depends(require_member)])


@members.get("/orders")
def list_orders() -> list[dict[str, int]]:
    return [{"id": 1}]


app.include_router(members)
